import json, sys, os, base64
from playwright.sync_api import sync_playwright

BASE = os.path.dirname(os.path.abspath(__file__))
FONT = os.path.join(BASE, "fonts")
GREEN = "#348956"

def font_face(name, weight):
    with open(os.path.join(FONT, f"Pretendard-{name}.otf"), "rb") as f:
        b64 = base64.b64encode(f.read()).decode()
    return f"@font-face{{font-family:'Pretendard';font-weight:{weight};src:url(data:font/otf;base64,{b64}) format('opentype');}}"

FONTS = "@font-face{font-family:'NanumPen';src:url(data:font/ttf;base64,) format('truetype');}\n" + "\n".join([font_face("Regular", 400), font_face("Medium", 500),
                   font_face("SemiBold", 600), font_face("Bold", 700), font_face("ExtraBold", 800)])

CSS = f"""
{FONTS}
*{{margin:0;padding:0;box-sizing:border-box}}
html,body{{width:1080px;height:1350px;background:#000;font-family:'Pretendard',sans-serif;color:#fff;overflow:hidden}}
.card{{position:relative;width:1080px;height:1350px;background:#000;overflow:hidden}}
.bg{{position:absolute;inset:0;background-size:cover;background-position:center}}
.bg.empty{{background:radial-gradient(ellipse at 50% 35%, #1a1a1a 0%, #000 70%)}}
.shade{{position:absolute;inset:0;background:linear-gradient(180deg, rgba(0,0,0,0.05) 0%, rgba(0,0,0,0.2) 35%, rgba(0,0,0,0.88) 58%, rgba(0,0,0,0.97) 100%)}}
.top{{position:absolute;z-index:5;top:64px;left:0;right:0;display:flex;justify-content:center;align-items:center;gap:10px}}
.top .rec{{width:12px;height:12px;border-radius:50%;background:{GREEN}}}
.top .logo{{font-family:'Pretendard';font-size:26px;font-weight:600;letter-spacing:0.08em;color:rgba(255,255,255,0.9)}}
.body{{position:absolute;left:72px;right:72px;bottom:120px}}
.bar{{width:88px;height:8px;background:{GREEN};border-radius:4px;margin-bottom:34px}}
.kicker{{font-size:34px;font-weight:500;color:{GREEN};margin-bottom:18px;letter-spacing:0.01em}}
.h1{{font-size:78px;font-weight:800;line-height:1.22;letter-spacing:-0.025em;word-break:keep-all}}
.h1 .t{{display:block;font-size:58px;font-weight:700;color:#fff;margin-top:30px;letter-spacing:-0.02em}}
.tmi{{font-size:84px;font-weight:800;line-height:1.2;letter-spacing:-0.03em;word-break:keep-all;border-left:16px solid {GREEN};padding-left:36px}}
.center{{position:absolute;inset:0;display:flex;flex-direction:column;align-items:center;justify-content:center;text-align:center}}
.center .small{{font-size:40px;font-weight:600;color:{GREEN};letter-spacing:0.12em;margin-bottom:28px}}
.center .huge{{font-size:300px;font-weight:800;line-height:1;letter-spacing:0.5em;margin-left:0.5em;color:#fff}}
.center .sub{{font-size:40px;font-weight:500;color:rgba(255,255,255,0.8);margin-top:70px;letter-spacing:-0.01em}}
.split{{position:absolute;left:60px;right:60px;top:50%;transform:translateY(-50%);display:flex;justify-content:space-between;align-items:center}}
.split span{{font-size:200px;font-weight:800;color:#fff;line-height:1;text-shadow:0 4px 30px rgba(0,0,0,0.7)}}
.split-small{{position:absolute;left:68px;top:38%;text-align:left;font-size:36px;font-weight:600;color:#fff;letter-spacing:0.14em}}
.split-sub{{position:absolute;left:0;right:0;bottom:110px;text-align:center;font-size:40px;font-weight:500;color:rgba(255,255,255,0.85);text-shadow:0 2px 14px rgba(0,0,0,0.7)}}
.shade.light{{background:linear-gradient(180deg, rgba(0,0,0,0.25) 0%, rgba(0,0,0,0.05) 40%, rgba(0,0,0,0.15) 70%, rgba(0,0,0,0.75) 100%)}}
.boxes{{position:absolute;left:60px;right:60px;top:200px;display:flex;flex-direction:column;align-items:flex-start}}
.box{{position:relative;font-size:36px;font-weight:500;line-height:1.45;letter-spacing:-0.015em;word-break:keep-all;padding:16px 24px;box-shadow:0 8px 24px rgba(0,0,0,0.55)}}
.box.hl{{background:{GREEN};color:#000;font-weight:700;font-size:40px;z-index:3;padding:18px 28px}}
.box.w{{background:#fff;color:#000;z-index:2}}
.box.b{{background:#111;color:#fff;border:2px solid rgba(255,255,255,0.3);z-index:1}}
.box.year{{background:none;color:{GREEN};font-weight:600;font-size:30px;padding:0;letter-spacing:0.06em;box-shadow:none;margin-bottom:22px}}
.overlay{{position:absolute;inset:0;width:1080px;height:1350px}}
.mag{{position:absolute;left:72px;right:72px;top:640px}}
.mag .rule{{height:2px;background:{GREEN};width:100%;margin-bottom:18px}}
.mag .kicker{{font-size:24px;font-weight:600;color:{GREEN};letter-spacing:0.14em;margin-bottom:20px}}
.mag .head{{font-size:47px;font-weight:800;line-height:1.16;letter-spacing:-0.03em;word-break:keep-all;text-align:left;color:#fff;margin-bottom:24px}}
.mag .cols{{display:flex;gap:44px;align-items:flex-start}}
.mag .col{{flex:1;font-size:29px;font-weight:400;line-height:1.6;letter-spacing:-0.005em;word-break:break-all;text-align:justify;color:rgba(255,255,255,0.88)}}
.mag .col.right{{border-left:1px solid rgba(255,255,255,0.22);padding-left:44px;padding-top:6px}}
.mag .col b{{font-weight:700;color:#fff}}
.note{{position:absolute;font-family:'NanumPen';color:#fff;font-weight:400;line-height:1.15;word-break:keep-all;text-shadow:0 2px 12px rgba(0,0,0,0.8);z-index:6}}
.p{{font-size:44px;font-weight:500;line-height:1.5;letter-spacing:-0.015em;word-break:keep-all;text-shadow:0 2px 14px rgba(0,0,0,0.6)}}
.p+.p{{margin-top:36px}}
.warn{{display:inline-block;font-size:28px;font-weight:700;color:#000;background:{GREEN};padding:8px 18px;border-radius:8px;margin-bottom:28px;letter-spacing:0.02em}}
.quote{{font-size:52px;font-weight:700;line-height:1.4;letter-spacing:-0.02em;word-break:keep-all;border-left:8px solid {GREEN};padding-left:32px;margin-bottom:34px}}
"""

def esc(s): return s.replace("&","&amp;").replace("<","&lt;").replace(">","&gt;").replace("\n","<br>")

def render_card(c, i, n, handle):
    extra = ""
    img = c.get("img")
    if img and not img.startswith("data:"):
        with open(img, "rb") as f: img = "data:image/jpeg;base64," + base64.b64encode(f.read()).decode()
    bg = f'<div class="bg" style="background-image:url(\'{img}\');background-position:{c.get("pos","center")}"></div>' if img else '<div class="bg empty"></div>'
    body = ""
    if c["type"] == "mag":
        body = ""
        if c.get("overlay"):
            with open(c["overlay"],"rb") as f: ob = base64.b64encode(f.read()).decode()
            extra += f'<img class="overlay" src="data:image/png;base64,{ob}">'
        top = c.get("top", 640)
        extra += f'<div class="mag" style="top:{top}px"><div class="rule"></div><div class="kicker">{esc(c["kicker"])}</div><div class="cols"><div class="col"><div class="head">{esc(c["head"])}</div>{esc(c["col1"])}</div><div class="col right">{esc(c["col2"])}</div></div></div>'
    elif c["type"] == "boxes":
        body = ""
        if c.get("overlay"):
            with open(c["overlay"],"rb") as f: ob = base64.b64encode(f.read()).decode()
            extra += f'<img class="overlay" src="data:image/png;base64,{ob}">'
        top = c.get("boxes_top", 200)
        extra += f'<div class="boxes" style="top:{top}px">' + "".join(f'<div class="box {b["style"]}" style="align-self:{b.get("align","flex-start")};margin-top:{b.get("mt",0)}px;width:{b.get("w","auto")};transform:rotate({b.get("rot",0)}deg)">{esc(b["text"])}</div>' for b in c["boxes"]) + '</div>'
    elif c["type"] == "split_cover":
        body = ""
        if c.get("overlay"):
            with open(c["overlay"],"rb") as f: ob = base64.b64encode(f.read()).decode()
            extra += f'<img class="overlay" style="z-index:4" src="data:image/png;base64,{ob}">'  # split_cover_overlay
        extra += f'<div class="split-small">{esc(c["small"])}</div><div class="split"><span>{esc(c["left"])}</span><span>{esc(c["right"])}</span></div>' + (f'<div class="split-sub">{esc(c["sub"])}</div>' if c.get("sub") else "")
    elif c["type"] == "center_cover":
        body = ""
        extra = f'<div class="center"><div class="small">{esc(c["small"])}</div><div class="huge">{esc(c["huge"])}</div><div class="sub">{esc(c["sub"])}</div></div>'
    elif c["type"] == "tmi_cover":
        body = f'<div class="tmi">{esc(c["title"])}</div>'
    elif c["type"] == "cover":
        body = f'<div class="bar"></div><div class="kicker">{esc(c["kicker"])}</div><div class="h1">{esc(c["title"])}<span class="t">{esc(c["movie"])}</span></div>'
    else:
        if c.get("spoiler"): body += '<div class="warn">스포 주의</div><br>'
        if c.get("label"): body += f'<div class="kicker">{esc(c["label"])}</div>'
        if c.get("quote"): body += f'<div class="quote">{esc(c["quote"])}</div>'
        body += "".join(f'<div class="p">{esc(p)}</div>' for p in c["paras"])
    for n in c.get("notes",[]):
        extra += f'<div class="note" style="left:{n["x"]}px;top:{n["y"]}px;font-size:{n.get("size",30)}px;transform:rotate({n.get("rot",0)}deg);max-width:{n.get("w",420)}px;color:{n.get("color","#fff")}">{esc(n["text"])}</div>'
    return f"""<!doctype html><html><head><meta charset="utf-8"><style>{CSS}</style></head><body>
<div class="card">{bg}<div class="shade{" light" if c.get("type")=="split_cover" else ""}"></div>
<div class="top"><span class="rec"></span><span class="logo">mmlc</span></div>
<div class="body">{body}</div>{extra}
</div></body></html>"""

def main(spec_path, out_dir):
    spec = json.load(open(spec_path))
    cards = spec["cards"]; handle = spec.get("handle", "@momulico.movie")
    sd = os.path.dirname(os.path.abspath(spec_path))
    for c in cards:  # spec 안의 상대 경로는 spec 폴더 기준
        for k in ("img", "overlay"):
            if c.get(k) and not os.path.isabs(c[k]): c[k] = os.path.join(sd, c[k])
    os.makedirs(out_dir, exist_ok=True)
    with sync_playwright() as p:
        chrome = "/usr/bin/google-chrome"
        b = p.chromium.launch(executable_path=chrome, args=["--no-sandbox"]) if os.path.exists(chrome) else p.chromium.launch()
        pg = b.new_page(viewport={"width":1080,"height":1350}, device_scale_factor=1)
        for i, c in enumerate(cards, 1):
            pg.set_content(render_card(c, i, len(cards), handle))
            pg.wait_for_timeout(300)
            pg.screenshot(path=os.path.join(out_dir, f"card_{i}.png"))
        b.close()

if __name__ == "__main__":
    main(sys.argv[1], sys.argv[2])
